#include <iostream>
#include <memory>
#include <stdexcept>

extern "C" {
struct CCounter { int value; };
inline CCounter* c_create(int start) { return new CCounter{start}; }
inline void c_destroy(CCounter* c) { delete c; }
inline int c_add(CCounter* c, int n) { if (!c) return 1; c->value += n; return 0; }
}

namespace xn
{
class Counter
{
public:
    explicit Counter(int start) {}
};
}

int main()
{
    xn::Counter c{10};
}
